import{_ as a,c as e,o as t,af as i}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"《雜卦傳》簡介","description":"易傳 - 《雜卦傳》簡介","frontmatter":{"title":"《雜卦傳》簡介","description":"易傳 - 《雜卦傳》簡介"},"headers":[],"relativePath":"classics/yizhuan/006.md","filePath":"classics/yizhuan/006.md"}'),s={name:"classics/yizhuan/006.md"};function l(r,p,n,c,_,o){return t(),e("div",null,[...p[0]||(p[0]=[i('<h1 id="《雜卦傳》簡介" tabindex="-1">《雜卦傳》簡介 <a class="header-anchor" href="#《雜卦傳》簡介" aria-label="Permalink to “《雜卦傳》簡介”">​</a></h1><p>其功能作用主要體現在對《周易》六十四卦卦義及相互關係的精煉總結與點評。它打亂了六十四卦的常規排列順序，以兩兩相對的方式，用極其凝鍊的語言歸納了各卦的卦義，使得原本紛繁複雜的卦象變得簡潔明瞭，易於記憶。</p><p>此外，《雜卦傳》還通過對比各卦之間的異同，幫助讀者深入理解各卦的內涵及其相互關係。這種以對比方式進行的學習，有助於讀者培養反向思維和全面觀察事物的能力，從而更全面地把握《周易》的精髓。</p><p>雜卦傳</p><p>《乾》剛《坤》柔，《比》樂《師》憂；《臨》《觀》之義，或與或求。</p><p>《屯》見而不失其居。《蒙》雜而著。《震》，起也。《艮》，止也。《損》、《益》盛衰之始也。</p><p>《大畜》，時也。《無妄》，災也。《萃》聚而《升》不來也。《謙》輕而《豫》怠也。</p><p>《噬嗑》，食也。《賁》，無色也。《兌》見而《巽》伏也。《隨》無故也。《蠱》則飭也。</p><p>《剝》，爛也。《復》，反也。《晉》，晝也。《明夷》，誅也。《井》通而《困》相遇也。</p><p>《鹹》速也。《恆》，久也。《渙》，離也。《節》，止也。《解》，緩也。《蹇》，難也。</p><p>《睽》，外也。《家人》，內也。《否》、《泰》反其類也。《大壯》則止，《遯》則退也。</p><p>《大有》，眾也。《同人》，親也。《革》，去故也。《鼎》，取新也。</p><p>《小過》，過也。《中孚》，信也。《豐》，多故也。親寡《旅》也。</p><p>《離》上而《坎》下也。《小畜》，寡也。《履》，不處也。《需》，不進也。</p><p>《訟》，不親也。《大過》，顛也。《姤》，遇也，柔遇剛也。《漸》，女歸待男行也。</p><p>《頤》，養正也。《既濟》，定也。《歸妹》，女之終也。《未濟》，男之窮也。</p><p>《夬》，決也，剛決柔也。君子道長，小人道憂也。</p><p>《雜卦傳》要說明了《易經》六十四卦之間的錯綜關係，以相反相成的觀點將六十四卦分為三十二對，兩兩一組進行解釋，揭示了各卦的卦義和相互關係。</p><p>《雜卦傳》特徵</p><ul><li><p>分類解讀 ：以相反或相成的觀點，將六十四卦分為三十二對，每對卦象通過一兩個字來概括其主要含義和相互關係。</p></li><li><p>言簡意賅 ：《雜卦傳》的言辭非常簡潔，或以一字釋一卦，或數字釋一卦，這種表述方式既精煉又富有哲理。</p></li><li><p>互補印證 ：《雜卦傳》與《序卦傳》互相補充印證，共同揭示了《易經》卦象之間的深刻內涵。</p></li></ul>',20)])])}const h=a(s,[["render",l]]);export{f as __pageData,h as default};
